class Solution:
    def maximumLength(self, s: str) -> int:
        counts = {}
        n = len(s)
        for i in range(n):
            j = i
            while j < n and s[i] == s[j]:
                j += 1
            length = j - i
            char = s[i]
            if char not in counts:
                counts[char] = []
            counts[char].append(length)
            i = j - 1

        ans = -1
        for char in counts:
            lengths = sorted(counts[char], reverse=True)

            if len(lengths) >= 3:
                ans = max(ans, lengths[2])
            elif len(lengths) == 2:
                ans = max(ans, 0)
            else:
                ans = max(ans, -1)

            if len(lengths) >= 1:
                l1 = lengths[0]
                if len(lengths) >= 2:
                    l2 = lengths[1]
                    if len(lengths) >= 3:
                        l3 = lengths[2]
                    else:
                        l3 = 0
                else:
                    l2 = 0
                    l3 = 0

                if len(lengths) >= 3:
                     ans = max(ans, l3)
                elif len(lengths) == 2:

                   if l1 >= 1 and l2>=1:

                      if l1 >= 1 and l2 >= 1 :
                        if (
                                l1 >=1 and l2 >=1
                        ): return 0

                else:
                   ans=max(ans, -1)     

            temp = []
            for l in lengths:
                temp.append(l)

            if len(temp) >= 1:
                l1 = temp[0]
                if len(temp) >= 2:
                    l2 = temp[1]
                    if len(temp) >= 3:
                        l3 = temp[2]
                    else:
                        l3=0
                else:
                         l2 = 0
                         l3 = 0

                occurences = []

                for l in temp:
                  occurences.append(l)

                possible_ans = -1
                for k in range(1, 51):
                       count = 0
                       for o in occurences:
                              if o >= k:
                                     count += 1

                       if count >= 3:
                            possible_ans = k

                if possible_ans != -1:
                       ans = max(ans, possible_ans)
                else:
                    pass


        return ans
